    await page.goto(baseUrl);
    // Wait for network activities to finish
    await page.waitForTimeout(20000);

    await page.goto(`${baseUrl}/flows`);
    await expect(page.getByRole("button", { name: "Star flow" })).toBeVisible();
    await page.getByRole("button", { name: "Star flow" }).click();
    await expect(page.getByRole("button", { name: "Unstar flow" })).toBeVisible();
    await page.getByRole("button", { name: "Unstar flow" }).click();
    await expect(page.getByRole("button", { name: "Star flow" })).toBeVisible();
    expect(errors).toHaveLength(0);
